package dev.altencir.orders.read;
import static org.mockito.Mockito.*; import com.fasterxml.jackson.databind.ObjectMapper; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import dev.altencir.orders.event.OrderPlacedV1; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import java.math.BigDecimal; import java.time.*; import java.util.UUID; import org.junit.jupiter.api.Test;
class OrderSummaryProjectorTest {
 @Test void ignoresAlreadyProcessedEvent() throws Exception {var summaries=mock(OrderSummaryRepository.class);var processed=mock(ProcessedEventRepository.class);var json=new ObjectMapper().registerModule(new JavaTimeModule());var event=new OrderPlacedV1(UUID.randomUUID(),"OrderPlaced",1,UUID.randomUUID(),"c",1,BigDecimal.TEN,Instant.now());when(processed.existsById(event.eventId())).thenReturn(true);new OrderSummaryProjector(summaries,processed,json,Clock.systemUTC(),new SimpleMeterRegistry()).project(json.writeValueAsString(event));verifyNoInteractions(summaries);verify(processed,never()).save(any());}
 @Test void storesProjectionAndCheckpointTogether() throws Exception {var summaries=mock(OrderSummaryRepository.class);var processed=mock(ProcessedEventRepository.class);var json=new ObjectMapper().registerModule(new JavaTimeModule());var event=new OrderPlacedV1(UUID.randomUUID(),"OrderPlaced",1,UUID.randomUUID(),"c",1,BigDecimal.TEN,Instant.now());new OrderSummaryProjector(summaries,processed,json,Clock.systemUTC(),new SimpleMeterRegistry()).project(json.writeValueAsString(event));verify(summaries).save(any());verify(processed).save(any());}
}
